```python
def print_board(board):
    """Print the current board state."""
    print("\n" + "   |   |   ")
    for row in range(3):
        print(f"{row + 1} | {board[row * 3][0]} | {board[row * 3][1]} | {board[row * 3][2]}" + " |")
        if row != 2:
            print("   |   |   ")

def get_user_input():
    """Get user input for a move."""
    while True:
        try:
            user_input = input("Enter a row (1-3) and column (1-3): ").strip()
            row, col = map(int, user_input.split())
            if 1 <= row <= 3 and 1 <= col <= 3:
                return row - 1, col - 1
            else:
                print("Invalid input. Please enter a row and column between 1 and 3.")
        except ValueError:
            print("Invalid input. Please enter a row and column separated by a space.")

def is_valid_move(board, row, col):
    """Check if the given move is valid."""
    return 0 <= row < 3 and 0 <= col < 3 and board[row][col] == " "

def play_tic_tac_toe():
    """Play a game of Tic-Tac-Toe."""
    board = [[" "] * 3 for _ in range(3)]
    player = "X"

    while True:
        print_board(board)
        row, col = get_user_input()
        if is_valid_move(board, row, col):
            board[row][col] = player
            if check_win(board, player):
                print_board(board)
                print(f"You won! {player}.")
                break
            elif is_full(board):
                print_board(board)
                print("It's a tie!")
                break
            else:
                player = "O" if player == "X" else "X"
        else:
            print("Invalid move. Please enter a valid row and column.")

def check_win(board, player):
    """Check for a win based on horizontal, vertical, and diagonal lines."""
    for row in board:
        if row[0] == player and row[1] == player and row[2] == player:
            return True

    for col in range(3):
        if board[0][col] == player and board[1][col] == player and board[2][col] == player:
            return True

    if board[0][0] == player and board[1][1] == player and board[2][2] == player:
        return True

    if board[0][2] == player and board[1][1] == player and board[2][0] == player:
        return True

    return False

def is_full(board):
    """Check if the board is full."""
    for row in board:
        for cell in row:
            if cell == " ":
                return False
    return True

if __name__ == "__main__":
    play_tic_tac_toe()
```

This program allows the user to play a game of Tic-Tac-Toe against the computer. You can modify the `play_tic_tac_toe` function to implement other game rules or add more features, such as a second player or a more complex game board.
